// Optional image art. Drop PNG files into public/art/… (see ART-PROMPTS.md) and they are used automatically.
// art/index.json lists what exists (generated by the deploy workflow, by server.js, or by `npm run art`).
export const slug = name => name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '');
export function artPath(card) {
  if (card.type === 'cat') return `art/cats/${slug(card.name)}.png`;
  if (card.type === 'toy') return `art/toys/${card.toy}.png`;
  if (card.type === 'costume') return `art/costumes/${slug(card.name)}.png`;
  if (card.type === 'food') return `art/items/${card.food}.png`;
  return `art/items/${card.type === 'lost' ? 'lost-cat' : card.type === 'spray' ? 'spray-bottle' : card.type}.png`;
}
export const EXTRA_ART = { back: 'art/card-back.png', token: 'art/cat-token.png', table: 'art/table.jpg', vp: 'art/vp-token.png', logo: 'art/logo.png' };
let available = new Set();
let onChange = null;
export function setArtListener(fn) { onChange = fn; }
export function hasArt(path) { return available.has(path); }
export async function probeAll() {
  try {
    const r = await fetch('art/index.json', { cache: 'no-cache' });
    if (!r.ok) return;
    const list = await r.json();
    if (Array.isArray(list)) { available = new Set(list); if (available.size && onChange) onChange(); }
  } catch { /* no art */ }
}
